  function knotsQ(R, L) {
    var d = R.pick([200, 250, 300, 340, 400]), s = R.pick([5, 10, 12, 20]), area = s * s, k = d * area;
    var f = function (x) { return x.toLocaleString('en-US'); };
    return P('A knotted carpet has ' + d + ' knots in every square inch. How many knots are in a ' + s + '-inch by ' + s + '-inch section?', mc(R, f(k), [f(k / 10), f(k * 10), f(d * s * 4), f(d + area)], nChoices(L)),
      [s + ' × ' + s + ' = ' + area + ' square inches.', area + ' × ' + d + ' = ' + f(k) + ' knots, each tied by hand.'], 'Find the area first.');
  }
